let audioCtx=null,masterGain=null,musicGain=null,uiGain=null,battleGain=null,compressor=null,noiseBuffer=null,musicTimer=null,musicPhase=0,lastCaptureSfx=0,lastDamageSfx=0,lastSliderSfx=0;
function ensureAudio(){if(!prefs.sound)return false;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();if(!masterGain){masterGain=audioCtx.createGain();musicGain=audioCtx.createGain();uiGain=audioCtx.createGain();battleGain=audioCtx.createGain();compressor=audioCtx.createDynamicsCompressor();compressor.threshold.value=-14;compressor.knee.value=18;compressor.ratio.value=4;compressor.attack.value=.003;compressor.release.value=.16;musicGain.connect(masterGain);uiGain.connect(masterGain);battleGain.connect(masterGain);masterGain.connect(compressor);compressor.connect(audioCtx.destination);const n=audioCtx.sampleRate*.32|0;noiseBuffer=audioCtx.createBuffer(1,n,audioCtx.sampleRate);const d=noiseBuffer.getChannelData(0);for(let i=0;i<n;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/n,.62)}applyAudioPrefs();return true}catch(e){return false}}
function applyAudioPrefs(){if(!audioCtx||!masterGain)return;const t=audioCtx.currentTime;masterGain.gain.setTargetAtTime(prefs.sound?(.18+.82*(prefs.volume||0)/100):0,t,.025);musicGain.gain.setTargetAtTime(prefs.music?(.15+.85*(prefs.musicVolume||0)/100)*.72:0,t,.07);uiGain.gain.setTargetAtTime(prefs.uiSounds?(.2+.8*(prefs.uiVolume||0)/100)*1.05:0,t,.025);battleGain.gain.setTargetAtTime(prefs.battleSounds?(.2+.8*(prefs.battleVolume||0)/100)*1.12:0,t,.025)}
function tone(freq=440,dur=.07,type='sine',vol=.05,delay=0,group='ui',slide=0){if(!prefs.sound||!ensureAudio())return;if(group==='ui'&&!prefs.uiSounds||group==='battle'&&!prefs.battleSounds||group==='music'&&!prefs.music)return;const now=audioCtx.currentTime+delay,o=audioCtx.createOscillator(),g=audioCtx.createGain(),dest=group==='music'?musicGain:group==='battle'?battleGain:uiGain,boost=group==='battle'?1.75:group==='ui'?1.55:1.25;o.type=type;o.frequency.setValueAtTime(Math.max(30,freq),now);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(30,slide),now+dur);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(Math.min(.32,Math.max(.0003,vol*boost)),now+.008);g.gain.exponentialRampToValueAtTime(.0001,now+dur);o.connect(g);g.connect(dest);o.start(now);o.stop(now+dur+.03)}
function noise(dur=.07,vol=.025,delay=0,filterFreq=900){if(!prefs.sound||!prefs.battleSounds||!ensureAudio()||!noiseBuffer)return;const now=audioCtx.currentTime+delay,src=audioCtx.createBufferSource(),f=audioCtx.createBiquadFilter(),g=audioCtx.createGain();src.buffer=noiseBuffer;f.type='lowpass';f.frequency.value=filterFreq;g.gain.setValueAtTime(Math.min(.26,vol*1.9),now);g.gain.exponentialRampToValueAtTime(.0001,now+dur);src.connect(f);f.connect(g);g.connect(battleGain);src.start(now);src.stop(now+dur)}
function soundEvent(name,intensity=1){if(!prefs.sound)return;switch(name){case'tap':tone(560,.045,'sine',.026,0,'ui',690);break;case'open':tone(345,.07,'sine',.026,0,'ui',515);tone(620,.08,'triangle',.018,.025,'ui',760);break;case'close':tone(560,.065,'sine',.024,0,'ui',370);break;case'slider':{const n=performance.now();if(n-lastSliderSfx<48)return;lastSliderSfx=n;tone(690,.027,'sine',.018,0,'ui');break}case'count':tone(460,.085,'triangle',.034,0,'ui');break;case'go':tone(510,.11,'triangle',.052,0,'battle');tone(820,.15,'sine',.032,.045,'battle');break;case'spawn':tone(220,.13,'triangle',.055,0,'battle',365);tone(505,.17,'sine',.035,.045,'battle');noise(.10,.026,.012,900);break;case'attack':tone(132,.10,'square',.048*intensity,0,'battle',94);noise(.085,.036*intensity,.006,760);tone(318,.09,'triangle',.024,.03,'battle',430);break;case'naval':tone(158,.15,'triangle',.050,0,'battle',320);noise(.12,.028,.015,1180);tone(410,.12,'sine',.018,.04,'battle');break;case'capture':{const n=performance.now();if(n-lastCaptureSfx<170)return;lastCaptureSfx=n;tone(315+Math.random()*55,.045,'triangle',.018,0,'battle',430);break}case'damage':{const n=performance.now();if(n-lastDamageSfx<300)return;lastDamageSfx=n;tone(108,.095,'sawtooth',.030,0,'battle',72);noise(.05,.014,0,520);break}case'land':tone(190,.12,'triangle',.052,0,'battle',390);noise(.11,.032,.012,900);tone(515,.13,'sine',.026,.055,'battle');break;case'repel':tone(175,.14,'sawtooth',.044,0,'battle',78);break;case'eliminate':tone(220,.14,'square',.052,0,'battle',118);tone(92,.24,'sine',.038,.08,'battle');break;case'lead':tone(430,.09,'sine',.035,0,'battle');tone(645,.14,'triangle',.030,.06,'battle');break;case'pause':tone(390,.085,'sine',.026,0,'ui',300);break;case'resume':tone(320,.085,'sine',.026,0,'ui',505);break;case'win':[523,659,784,1047].forEach((f,i)=>tone(f,.26,'triangle',.055,i*.09,'battle'));break;case'lose':[370,277,185].forEach((f,i)=>tone(f,.27,'sine',.048,i*.11,'battle'));break}}
function haptic(ms=15){if(!prefs.vibration||!navigator.vibrate)return;const mult={Light:.55,Medium:1,Strong:1.55}[prefs.hapticStrength]||1;if(Array.isArray(ms))navigator.vibrate(ms.map(x=>Math.round(x*mult)));else navigator.vibrate(Math.round(ms*mult))}
function clickFx(){soundEvent('tap');haptic(7)}
function stopMusic(){if(musicTimer){clearTimeout(musicTimer);musicTimer=null}}
function musicTick(){if(!prefs.sound||!prefs.music||!audioCtx)return;const inGame=screens.game?.classList.contains('active'),roots=inGame?[87.31,98,110,130.81,146.83]:[110,123.47,146.83,164.81,196],root=roots[musicPhase%roots.length],color=[1,1.2,1.5,1.333,1.8][(musicPhase*3)%5],space=2.8+Math.random()*2.3;musicPhase++;tone(root,space+.9,'sine',.020,0,'music');tone(root*color,1.4+Math.random()*1.3,'triangle',.009,.2+Math.random()*.25,'music');if(musicPhase%3===0)tone(root*2,.95,'sine',.0065,.65,'music');if(musicPhase%5===0)tone(root*.5,1.8,'sine',.008,.15,'music');musicTimer=setTimeout(musicTick,space*1000)}
function syncMusic(){if(!prefs.sound||!prefs.music){stopMusic();return}if(!ensureAudio())return;if(!musicTimer)musicTimer=setTimeout(musicTick,120)}

