// High-detail offline continent masks. Coastlines are derived from GSHHG shoreline data (LGPL)
// and continent selection uses Natural Earth country outlines (public domain). The masks are
// compressed with a tiny row-RLE codec so the game remains one self-contained offline HTML file.
const MAP_MASKS={"europe":{"w":1600,"h":810,"d":""},"asia":{"w":1800,"h":1068,"d":""},"oceania":{"w":1500,"h":1100,"d":""},"northAmerica":{"w":1700,"h":1105,"d":""},"southAmerica":{"w":1200,"h":1413,"d":""},"world":{"w":2000,"h":789,"d":""}};
const MAP_MASK_CACHE={};
function readVarint(bytes,state){let n=0,s=0,b;do{b=bytes[state.i++];n|=(b&127)<<s;s+=7}while(b&128);return n}
function decodeMapMask(id){if(MAP_MASK_CACHE[id])return MAP_MASK_CACHE[id];const m=MAP_MASKS[id]||MAP_MASKS.europe,bin=atob(m.d),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);const out=new Uint8Array(m.w*m.h),st={i:0};for(let y=0;y<m.h;y++){const rc=readVarint(bytes,st);let x=0,v=0;for(let r=0;r<rc;r++){const len=readVarint(bytes,st);if(v)out.fill(1,y*m.w+x,y*m.w+x+len);x+=len;v^=1}}return MAP_MASK_CACHE[id]={w:m.w,h:m.h,p:out}}

