function applyCustomPreset(data){const {map,difficulty,...rules}=data||{};prefs.custom={...DEFAULT_CUSTOM,...rules};if(map&&MAPS[map])prefs.map=map;if(difficulty&&DIFFS.includes(difficulty))prefs.difficulty=difficulty;savePrefs();syncCustomUI();renderMapButtons();renderDiffButtons();updatePlaySubtitle();setTimeout(drawAllMapPreviews,0);soundEvent('open')}
function renderPresetChips(){const g=$('#customPresetGrid');if(g){g.innerHTML='';for(const [name,v] of Object.entries(CUSTOM_TEMPLATES)){const b=document.createElement('button');b.className='presetChip';b.textContent=name;b.onclick=()=>applyCustomPreset(v);g.appendChild(b)}}const sg=$('#savedPresetGrid');if(sg){sg.innerHTML='';for(let i=0;i<prefs.customPresets.length;i++){const x=prefs.customPresets[i],b=document.createElement('button');b.className='presetChip';b.textContent=x.name;b.onclick=()=>applyCustomPreset(x.rules);b.oncontextmenu=e=>{e.preventDefault();prefs.customPresets.splice(i,1);savePrefs();renderPresetChips()};sg.appendChild(b)}}}
function syncCustomUI(){const c=prefs.custom,vals={customBots:c.bots,customStart:c.startTroops,customGrowth:Math.round(c.growth*100),customSpeed:Math.round(c.gameSpeed*100),customAttack:Math.round(c.attackSpeed*100),customNeutral:c.neutralStrength,customSpawn:c.spawnRadius,customPeace:c.peacefulStart,customTime:c.timeLimit,customVictory:c.victory,customNaval:c.navalRange};for(const [id,v] of Object.entries(vals)){const e=$('#'+id);if(e)e.value=v}const texts={customBotsValue:c.bots,customStartValue:fmt(c.startTroops),customGrowthValue:c.growth.toFixed(1)+'×',customSpeedValue:c.gameSpeed.toFixed(1)+'×',customAttackValue:c.attackSpeed.toFixed(1)+'×',customNeutralValue:c.neutralStrength+'%',customSpawnValue:'Radius '+c.spawnRadius,customPeaceValue:c.peacefulStart?c.peacefulStart+'s':'Off',customTimeValue:c.timeLimit?c.timeLimit+' min':'Off',customVictoryValue:c.victory+'%',customNavalValue:c.navalRange+'%'};for(const [id,t] of Object.entries(texts)){const e=$('#'+id);if(e)e.textContent=t}if($('#customBias'))$('#customBias').value=c.aiBias||'Balanced'}
