 const mapGrid=$('#mapGrid');mapGrid.innerHTML='';Object.entries(MAPS).forEach(([id,m])=>{const b=document.createElement('button');b.className='mapBtn'+(prefs.map===id?' sel':'');b.dataset.map=id;b.innerHTML=`<canvas class="mapPreview" width="360" height="180"></canvas><b>${m.name}</b><small>${m.desc}</small><span class="mapMeta"><i>${m.tag}</i><i>${Math.round(m.naval*100)}% NAVAL</i></span>`;b.onclick=()=>{clickFx();prefs.map=id;savePrefs();renderMapButtons();updatePlaySubtitle();setTimeout(drawAllMapPreviews,0)};mapGrid.appendChild(b)});
 const ds=$('#diffSegment');ds.innerHTML='';DIFFS.forEach(d=>{const b=document.createElement('button');b.className='segBtn'+(prefs.difficulty===d?' sel':'');b.textContent=d;b.onclick=()=>{clickFx();prefs.difficulty=d;savePrefs();renderDiffButtons();updatePlaySubtitle()};ds.appendChild(b)});
 const cg=$('#colorGrid');cg.innerHTML='';PALETTE.slice(0,12).forEach(c=>{const b=document.createElement('button');b.className='colorSwatch'+(prefs.color===c?' sel':'');b.style.background=c;b.dataset.color=c;b.onclick=()=>{clickFx();prefs.color=c;savePrefs();renderColors();updateProfileSurfaces()};cg.appendChild(b)});
 bindSettings();bindCustomControls();renderToggles();renderStats();renderDiffButtons();updatePlaySubtitle();updateCustomControls();renderPresetChips();setTimeout(drawAllMapPreviews,0);
