function generateMap(){const N=game.GW*game.GH,m=decodeMapMask(game.mapId);game.terrain=new Uint8Array(N);game.owner=new Int16Array(N);game.owner.fill(WATER);game.landCount=0;for(let y=0;y<game.GH;y++)for(let x=0;x<game.GW;x++){let land=0;for(const oy of [.15,.38,.62,.85])for(const ox of [.15,.38,.62,.85]){const sx=Math.min(m.w-1,Math.floor((x+ox)*m.w/game.GW)),sy=Math.min(m.h-1,Math.floor((y+oy)*m.h/game.GH));land+=m.p[sy*m.w+sx]}const i=y*game.GW+x;if(land>=4){game.terrain[i]=1;game.owner[i]=NEUTRAL;game.landCount++}}}

