function createPlayers(){const count=clamp(Math.round(game.rules.bots)+1,2,101),base=['aggressive','opportunist','defensive','expansionist','navigator'],bias=game.rules.aiBias||'Balanced',weights=bias==='Aggressive'?['aggressive','aggressive','opportunist','expansionist','navigator']:bias==='Defensive'?['defensive','defensive','opportunist','navigator','expansionist']:bias==='Naval'?['navigator','navigator','opportunist','aggressive','expansionist']:bias==='Expansion'?['expansionist','expansionist','navigator','opportunist','aggressive']:base;const names=new Set();function botName(){for(let q=0;q<50;q++){let n;if(gRandom()<.18)n=NATION_WORDS[(gRandom()*NATION_WORDS.length)|0];else n=BOT_FIRST[(gRandom()*BOT_FIRST.length)|0]+' '+BOT_LAST[(gRandom()*BOT_LAST.length)|0];if(!names.has(n)){names.add(n);return n}}return 'Commander '+(names.size+1)}game.players=[];for(let i=0;i<count;i++){const human=i===0,behavior=human?'human':weights[(gRandom()*weights.length)|0],avatar=human?(prefs.avatarImage?'custom':prefs.avatar):AVATARS[(gRandom()*AVATARS.length)|0];game.players.push({id:i,name:human?(prefs.name||'Player'):botName(),avatar,avatarImage:human?prefs.avatarImage:'',color:human?prefs.color:'#888',balance:game.rules.startTroops,cells:new Set(),border:new Set(),coast:new Set(),components:new Map(),alive:true,behavior,baseBehavior:human?'opportunist':behavior,think:gRand(1.1,.2),attacks:0,elims:0,recentLoss:0,recentGain:0,lastAttacker:-1,lastAttackedAt:-99,aiCursor:(i*37)%997})}}

