function colorCandidates(){const mode=prefs.colorblind,hues=mode==='Deuteranopia'?[210,35,285,190,330,55,245,15]:mode==='Protanopia'?[210,45,285,190,320,60,250,25]:mode==='Tritanopia'?[350,25,210,280,155,320,185,5]:[195,225,260,290,325,355,25,50,80,115,150,175];const arr=[];for(const sat of [62,78,90])for(const l of [36,46,56,66])for(const h of hues)arr.push(hslToHex(h,sat,l));return arr}
