// ---------- Territory topology / contacts ----------
function neighbors(i){const x=i%game.GW,y=(i/game.GW)|0,a=[];if(x>0)a.push(i-1);if(x<game.GW-1)a.push(i+1);if(y>0)a.push(i-game.GW);if(y<game.GH-1)a.push(i+game.GW);return a}
