function refreshBorderAround(i){refreshCellStatus(i);for(const n of neighbors(i))refreshCellStatus(n)}
function rebuildAllBorders(){for(const p of game.players){p.border.clear();p.coast.clear()}for(let i=0;i<game.owner.length;i++)if(game.owner[i]>=0)refreshCellStatus(i);game.contactDirty=true}
function changeComponentCount(p,cell,delta){const c=game.componentId[cell];if(c<0)return;const n=(p.components.get(c)||0)+delta;if(n<=0)p.components.delete(c);else p.components.set(c,n)}
