function handleElimination(victimId,killerId){const v=game.players[victimId],k=killerId>=0?game.players[killerId]:null;if(k){k.elims++;if(k.id===game.human)game.eliminations++}const text=k?`${k.name} eliminated ${v.name}`:`${v.name} was eliminated`;pushEvent(text,killerId===game.human?'good':victimId===game.human?'danger':'war');if(killerId===game.human||victimId===game.human){soundEvent('eliminate');haptic(killerId===game.human?[16,25,20]:[25,35,28])}if(game.inspected===victimId)inspectNation(victimId)}

// ---------- Rendering ----------
function hexToRgb(h){if(!h||h[0]!=='#')return[128,128,128];const n=parseInt(h.slice(1),16);return[(n>>16)&255,(n>>8)&255,n&255]}
function paintWholeWorld(){const img=wctx.createImageData(game.GW,game.GH);for(let i=0;i<game.owner.length;i++){const p=i*4,o=game.owner[i];let c;if(o===WATER){const x=i%game.GW,y=(i/game.GW)|0,n=(x*17+y*11)%31;c=[22+(n<4?2:0),61+(n<6?4:0),86+(n<8?5:0)]}else if(o===NEUTRAL)c=[104,119,113];else c=hexToRgb(game.players[o].color);img.data[p]=c[0];img.data[p+1]=c[1];img.data[p+2]=c[2];img.data[p+3]=255}wctx.putImageData(img,0,0);game.borderDirty=true;game.dirty=true}
