function computeLabels(){if(!game.players.length)return;const max=prefs.quality==='Low'?12:24,list=game.players.filter(p=>p.alive&&p.cells.size>=10).sort((a,b)=>b.cells.size-a.cells.size).slice(0,max);game.labels=[];for(const p of list){let sx=0,sy=0,n=0,k=0,step=Math.max(1,Math.floor(p.cells.size/180)),bestCell=-1;for(const cell of p.cells){if((k++%step)!==0)continue;sx+=cell%game.GW;sy+=(cell/game.GW)|0;n++}if(!n)continue;const ax=sx/n,ay=sy/n;let bd=Infinity;k=0;for(const cell of p.cells){if((k++%step)!==0)continue;const x=cell%game.GW,y=(cell/game.GW)|0,d=(x-ax)**2+(y-ay)**2;if(d<bd){bd=d;bestCell=cell}}if(bestCell>=0)game.labels.push({id:p.id,x:bestCell%game.GW+.5,y:((bestCell/game.GW)|0)+.5,cells:p.cells.size})}game.dirty=true}
