function resizeCanvas(){viewW=innerWidth;viewH=innerHeight;const maxD=prefs.batterySaver?1.25:prefs.quality==='High'?2:prefs.quality==='Medium'?1.6:1.25;dpr=clamp(devicePixelRatio||1,1,maxD);canvas.width=Math.floor(viewW*dpr);canvas.height=Math.floor(viewH*dpr);canvas.style.width=viewW+'px';canvas.style.height=viewH+'px';ctx.setTransform(dpr,0,0,dpr,0,0);ctx.imageSmoothingEnabled=false;clampCamera();game.dirty=true}
