// ---------- Combat / front lines ----------
function nearestOwnedCell(attacker,targetCell,maxDist,coastOnly=false){const tx=targetCell%game.GW,ty=(targetCell/game.GW)|0,p=game.players[attacker],set=coastOnly?p.coast:p.border.size?p.border:p.cells;let best=-1,bd=maxDist*maxDist;for(const i of set){const x=i%game.GW,y=(i/game.GW)|0,d=(x-tx)**2+(y-ty)**2;if(d<bd){bd=d;best=i}}return best}
function collectFrontSeeds(attacker,defender,targetCell,maxSeeds=9){const p=game.players[attacker],tx=targetCell>=0?targetCell%game.GW:0,ty=targetCell>=0?(targetCell/game.GW)|0:0,cand=[],seen=new Set();for(const c of p.border){for(const n of neighbors(c)){if(game.owner[n]!==defender||seen.has(n))continue;seen.add(n);const x=n%game.GW,y=(n/game.GW)|0,d=targetCell>=0?(x-tx)**2+(y-ty)**2:0;cand.push({n,d,src:c})}}cand.sort((a,b)=>a.d-b.d);const take=cand.slice(0,maxSeeds),seeds=take.map(x=>x.n),source=take[0]?.src??-1;return{seeds,source}}
function navalRangeCells(){return Math.max(8,Math.max(game.GW,game.GH)*(game.rules.navalRange/100))}
function resolveLandingCell(targetCell,defender,source){let best=targetCell,bd=Infinity,tx=targetCell%game.GW,ty=(targetCell/game.GW)|0;for(let r=0;r<=9;r++){let found=false;for(let y=Math.max(0,ty-r);y<=Math.min(game.GH-1,ty+r);y++)for(let x=Math.max(0,tx-r);x<=Math.min(game.GW-1,tx+r);x++){if(Math.abs(x-tx)!==r&&Math.abs(y-ty)!==r)continue;const i=y*game.GW+x;if(game.owner[i]!==defender)continue;let coast=false;for(const n of neighbors(i))if(game.owner[n]===WATER){coast=true;break}if(!coast)continue;const sx=source%game.GW,sy=(source/game.GW)|0,d=(x-sx)**2+(y-sy)**2;if(d<bd){bd=d;best=i;found=true}}if(found)break}return best}
function startNavalAttack(attacker,defender,pct,targetCell,quiet=false,sourceOverride=-1){const ap=game.players[attacker];if(targetCell<0||game.owner[targetCell]!==defender||!ap?.alive||ap.balance<35)return false;if(defender>=0&&game.time<(game.rules.peacefulStart||0)){if(attacker===game.human&&!quiet)flashNotice(`Peace period · ${Math.ceil(game.rules.peacefulStart-game.time)}s remaining`);return false}const maxRange=navalRangeCells(),source=sourceOverride>=0?sourceOverride:nearestOwnedCell(attacker,targetCell,maxRange,true);if(source<0)return false;const landing=resolveLandingCell(targetCell,defender,source),sx=source%game.GW,sy=(source/game.GW)|0,tx=landing%game.GW,ty=(landing/game.GW)|0,dist=Math.hypot(tx-sx,ty-sy);if(dist>maxRange)return false;const army=Math.max(18,ap.balance*(pct/100));if(army>=ap.balance&&ap.balance<45)return false;ap.balance-=army;const duration=(1.25+2.9*(dist/maxRange))/Math.max(.55,game.rules.attackSpeed);game.navals.push({attacker,defender,army,from:source,to:landing,targetCell,progress:0,duration,initialArmy:army});if(attacker===game.human){game.navalsLaunched++;soundEvent('naval');haptic(18);addFx(source,ap.color);addFx(landing,ap.color);flashNotice(`Naval invasion · ${fmt(army)} troops`);advanceTutorial('naval')}else{const me=humanPlayer();if(defender===game.human||(me&&army>me.balance*.6))pushEvent(`${ap.name} launched a naval invasion`,defender===game.human?'danger':'war')}return true}
function startAttack(attacker,defender,pct,quiet=false,targetCell=-1){if(game.over||game.paused||attacker<0||!game.players[attacker]?.alive)return false;const ap=game.players[attacker];if(ap.balance<22||defender===attacker||defender===WATER||ap.attacks>=3)return false;if(defender>=0&&game.time<(game.rules.peacefulStart||0)){if(attacker===game.human&&!quiet)flashNotice(`Peace period · ${Math.ceil(game.rules.peacefulStart-game.time)}s remaining`);return false}const front=collectFrontSeeds(attacker,defender,targetCell,attacker===game.human?9:7);if(!front.seeds.length)return targetCell>=0?startNavalAttack(attacker,defender,pct,targetCell,quiet):false;const army=Math.max(12,ap.balance*(pct/100));if(army>ap.balance)return false;ap.balance-=army;const seen=new Set(front.seeds),a={attacker,defender,army,initialArmy:army,frontier:[...front.seeds],seen,acc:0,dead:false,source:front.source,targetCell:targetCell>=0?targetCell:front.seeds[0],captured:0,reason:''};game.attacks.push(a);ap.attacks++;if(attacker===game.human){game.attacksLaunched++;if(!quiet){soundEvent('attack',Math.min(1.3,.7+army/Math.max(1,game.rules.startTroops)*.15));haptic(16);addFx(a.targetCell,ap.color);flashNotice(`${defender===NEUTRAL?'Expansion':'Attack'} · ${fmt(army)} committed`)}if(defender===NEUTRAL)advanceTutorial('neutralAttack');else advanceTutorial('enemyAttack')}else if(defender===game.human){const me=humanPlayer();if(me){me.lastAttacker=attacker;me.lastAttackedAt=game.time;const now=game.time;if(now-game.lastHeavyWarning>7&&army>Math.max(180,me.balance*.28)){game.lastHeavyWarning=now;pushEvent(`${ap.name} is attacking your ${borderDirection(a.targetCell)} border`,'danger');soundEvent('damage');haptic(14)}}}return true}
function cellDefenseCost(defender,cell){if(defender===NEUTRAL)return game.rules.neutralCost*(.88+gRandom()*.24);const p=game.players[defender],density=p.balance/Math.max(1,p.cells.size);let support=0;for(const n of neighbors(cell))if(game.owner[n]===defender)support++;const local=.88+support*.075;return clamp((3+Math.sqrt(Math.max(0,density))*1.55)*local,4,82)}
function processAttacks(dt){const rate=ATTACK_CELLS_PER_SEC*game.rules.attackSpeed;for(const a of game.attacks){if(a.dead)continue;a.acc+=dt*rate;let steps=Math.min(12,Math.floor(a.acc));a.acc-=steps;while(steps-->0&&!a.dead){let idx=-1;while(a.frontier.length){const span=Math.min(10,a.frontier.length),k=a.frontier.length-1-((gRandom()*span)|0);idx=a.frontier[k];a.frontier[k]=a.frontier[a.frontier.length-1];a.frontier.pop();if(game.owner[idx]===a.defender)break;idx=-1}if(idx<0){a.dead=true;a.reason='front ended';break}const att=game.players[a.attacker],def=a.defender>=0?game.players[a.defender]:null;if(!att?.alive){a.dead=true;a.reason='attacker eliminated';break}const cost=cellDefenseCost(a.defender,idx);if(a.army<=cost){a.army=0;a.dead=true;a.reason='repelled';break}a.army-=cost;if(def?.balance>0)def.balance=Math.max(0,def.balance-cost*.62);setOwner(idx,a.attacker,true);a.captured++;for(const n of neighbors(idx))if(game.owner[n]===a.defender&&!a.seen.has(n)){a.seen.add(n);a.frontier.push(n)}if(a.defender>=0&&def&&!def.alive){a.dead=true;a.reason='eliminated';break}}}
 for(let i=game.attacks.length-1;i>=0;i--)if(game.attacks[i].dead){const a=game.attacks[i],p=game.players[a.attacker];if(p)p.attacks=Math.max(0,p.attacks-1);if(a.attacker===game.human){if(a.captured===0&&a.reason==='repelled'){soundEvent('repel');flashNotice('Attack repelled — rebuild your reserve')}else if(a.captured>0&&a.army<=0)flashNotice(`Front stalled after ${a.captured} cells`);if(a.captured>Math.max(20,game.landCount*.012))pushEvent(`You gained ${a.captured} cells in one offensive`,'good')}game.attacks.splice(i,1)}
}
function processNavals(dt){if(game.navals.length)game.dirty=true;for(let i=game.navals.length-1;i>=0;i--){const n=game.navals[i];n.progress+=dt/n.duration;if(n.progress<1)continue;const current=game.owner[n.to],att=game.players[n.attacker];if(current===WATER||!att?.alive){game.navals.splice(i,1);continue}if(current===n.attacker){att.balance+=n.army*.35;game.navals.splice(i,1);continue}const cost=current===NEUTRAL?game.rules.neutralCost*3.2:clamp(10+Math.sqrt((game.players[current]?.balance||0)/Math.max(1,game.players[current]?.cells.size||1))*4,12,105);if(n.army>cost){const remaining=n.army-cost;if(current>=0&&game.players[current])game.players[current].balance=Math.max(0,game.players[current].balance-cost*.65);setOwner(n.to,n.attacker,true);const front=collectFrontSeeds(n.attacker,current,n.to,5);if(front.seeds.length&&att.attacks<3){game.attacks.push({attacker:n.attacker,defender:current,army:remaining,initialArmy:n.initialArmy,frontier:[...front.seeds],seen:new Set(front.seeds),acc:0,dead:false,source:n.to,targetCell:n.targetCell,captured:1,reason:''});att.attacks++}else att.balance+=remaining*.22;if(n.attacker===game.human){game.navalsSucceeded++;soundEvent('land');haptic([10,20,14]);addFx(n.to,att.color,'land');flashNotice('Naval landing secured');pushEvent('Your naval invasion established a beachhead','good')}}else{if(n.attacker===game.human){soundEvent('repel');haptic(22);addFx(n.to,'#ff5577');flashNotice('Naval landing repelled')}else if(current===game.human)pushEvent(`${att.name}'s naval landing was repelled`,'good')}game.navals.splice(i,1)}}
function cancelOneAttack(pid){let best=-1,bestArmy=0;for(let i=0;i<game.attacks.length;i++){const a=game.attacks[i];if(a.attacker===pid&&!a.dead&&a.army>bestArmy){best=i;bestArmy=a.army}}if(best>=0){const a=game.attacks[best];a.dead=true;a.reason='withdrawn';game.players[pid].balance+=a.army*.46}}

// ---------- Economy / strategic AI ----------
function economyEfficiency(p){if(!p?.alive||!p.cells.size)return 0;const density=p.balance/p.cells.size;let e=density<8?.42+density/8*.32:density<18?lerp(.74,1,(density-8)/10):density<=95?1:density<230?lerp(1,.70,(density-95)/135):.56;const share=p.cells.size/Math.max(1,game.landCount);e*=1-.20*Math.pow(share,.7);return clamp(e,.38,1)}
function growthRate(p){if(!p?.alive||!p.cells.size)return 0;return(.75+Math.pow(p.cells.size,.68)*1.16)*economyEfficiency(p)*game.rules.growth*(game.map.tempo||1)}
function desiredReserve(p){const share=p.cells.size/Math.max(1,game.landCount),targetDensity=12+10*Math.sqrt(Math.min(2,share*20)),base=p.cells.size*targetDensity+180;if(p.id===game.human)return base;const mult={aggressive:.88,defensive:1.18,opportunist:1.02,expansionist:.92,navigator:.98}[p.behavior]||1,fronts=[...(game.contacts[p.id]?.keys()||[])].filter(x=>x>=0).length,frontPressure=1+Math.min(.28,fronts*.045);return base*mult*frontPressure}
function updateEconomy(dt){for(const p of game.players){if(!p.alive)continue;p.balance+=growthRate(p)*dt;p.recentLoss*=Math.pow(.22,dt/8);p.recentGain*=Math.pow(.3,dt/7)}}
function aiDifficulty(){return{Easy:{interval:1.55,noise:28,mistake:.22,navalSamples:28,foresight:.62,threshold:18},Normal:{interval:1.02,noise:13,mistake:.09,navalSamples:48,foresight:1,threshold:10},Hard:{interval:.76,noise:6,mistake:.025,navalSamples:70,foresight:1.22,threshold:5},Insane:{interval:.56,noise:2,mistake:.005,navalSamples:96,foresight:1.42,threshold:1}}[prefs.difficulty]||{interval:1.02,noise:13,mistake:.09,navalSamples:48,foresight:1,threshold:10}}
function strategicRankings(){return game.players.filter(p=>p.alive).sort((a,b)=>b.cells.size-a.cells.size)}
function evaluateContact(pid,target,info,d){const p=game.players[pid],traits=PERSONALITIES[p.behavior],share=p.cells.size/game.landCount;if(target===NEUTRAL){let score=36*traits.neutral+Math.min(28,info.count*.7)-share*28;if(p.balance<desiredReserve(p)*.70)score-=22;return score}const e=game.players[target];if(!e?.alive)return-999;const ratio=p.balance/Math.max(1,e.balance),weak=e.recentLoss/Math.max(1,e.cells.size),growthThreat=e.recentGain/Math.max(1,e.cells.size),leader=game.lastLeader===target?1:0,threat=e.balance/Math.max(1,p.balance);let score=(ratio-1)*32*d.foresight+weak*22+(p.cells.size>e.cells.size?5:-3)+leader*12;if(growthThreat>.035)score+=(ratio>.72?Math.min(13,growthThreat*80):-8)*d.foresight;if(p.behavior==='aggressive')score+=10*(ratio>.75);if(p.behavior==='defensive'){score-=8;if(p.lastAttacker===target&&game.time-p.lastAttackedAt<25)score+=24*traits.revenge}if(p.behavior==='opportunist')score+=weak*36+(e.attacks>0?10:0);if(p.behavior==='expansionist')score-=4;if(threat>1.7&&ratio<.7)score-=30;if(e.id===game.human&&prefs.difficulty==='Easy')score-=8;return score}
function chooseAttackPct(p,target,info,d){const reserve=desiredReserve(p),floorMult={aggressive:.46,defensive:.82,opportunist:.67,expansionist:.56,navigator:.62}[p.behavior]||.65,spendable=Math.max(0,p.balance-reserve*floorMult);if(spendable<12)return 0;const targetPower=target===NEUTRAL?Math.max(58,info.count*5.5):game.players[target].balance*(.31+.12*d.foresight)+info.count*4.5;let army;if(target===NEUTRAL)army=Math.min(spendable,Math.max(70,Math.min(p.balance*.24,targetPower*.78)));else{const cap=p.balance*(p.behavior==='aggressive'?.68:p.behavior==='defensive'?.43:.56);army=Math.min(spendable,cap,Math.max(targetPower,spendable*.48))}let pct=army/Math.max(1,p.balance)*100;if(gRandom()<d.mistake)pct*=gRand(1.30,.68);return clamp(pct,12,p.behavior==='aggressive'?76:68)}
function sampleSet(set,max){const out=[],n=set.size;if(!n)return out;const step=Math.max(1,Math.floor(n/max));let k=0;for(const v of set)if(k++%step===0){out.push(v);if(out.length>=max)break}return out}
function sampleArray(arr,max,offset=0){const out=[],n=arr.length;if(!n)return out;const step=Math.max(1,Math.floor(n/max));for(let k=0;k<n&&out.length<max;k+=step)out.push(arr[(k+offset)%n]);return out}
function findAINavalPlan(pid,d){const p=game.players[pid],traits=PERSONALITIES[p.behavior];if(!p.coast.size)return null;const sources=sampleSet(p.coast,p.behavior==='navigator'?18:12),maxRange=navalRangeCells();if(!sources.length)return null;let best=null,bestScore=-999;const compOffset=(p.aiCursor=(p.aiCursor+3)%97);for(const comp of game.components){if(p.components.has(comp.id)||!comp.coasts.length)continue;const targetSamples=sampleArray(comp.coasts,Math.min(10,Math.max(4,Math.round(d.navalSamples/10))),compOffset%Math.max(1,comp.coasts.length));for(const target of targetSamples){const owner=game.owner[target];if(owner===WATER||owner===pid)continue;const tx=target%game.GW,ty=(target/game.GW)|0;let source=-1,dist=Infinity;for(const c of sources){const dx=c%game.GW-tx,dy=((c/game.GW)|0)-ty,dd=Math.hypot(dx,dy);if(dd<dist){dist=dd;source=c}}if(source<0||dist>maxRange||dist<4)continue;let score=28+Math.log2(comp.size+1)*3.3-dist/maxRange*17+Math.min(12,localLandScore(target,4)*.55);if(owner===NEUTRAL)score+=25*traits.neutral;else{const e=game.players[owner];if(!e?.alive)continue;const ratio=p.balance/Math.max(1,e.balance);if(ratio<.48&&p.behavior!=='aggressive')continue;score+=(ratio-1)*24+e.recentLoss/Math.max(1,e.cells.size)*34+(game.lastLeader===owner?11:0);if(e.attacks>0&&p.behavior==='opportunist')score+=10}if(p.behavior==='navigator')score+=16;if(p.behavior==='expansionist'&&owner===NEUTRAL)score+=8;if(score>bestScore){bestScore=score;best={target,owner,source,score,newComponent:true,distance:dist}}}}return bestScore>d.threshold*.4?best:null}
function componentSaturation(p){let capacity=0;for(const [cid] of p.components)capacity+=game.components[cid]?.size||0;return p.cells.size/Math.max(p.cells.size,capacity)}
function chooseAIFrontCell(pick,d){const samples=pick?.info?.samples||[];if(!samples.length)return-1;if(d.mistake>.18&&gRandom()<d.mistake)return samples[(gRandom()*samples.length)|0];let best=samples[0],bestScore=-1e9;for(const cell of samples){let friendly=0,enemy=0;for(const n of neighbors(cell)){const o=game.owner[n];if(o===pick.target)enemy++;else if(o>=0)friendly++}let score=pick.target===NEUTRAL?(4-enemy)*3+localLandScore(cell,3)*.18:(4-enemy)*5+friendly*1.4;if(game.coastCells&&game.componentId[cell]>=0)score+=(game.components[game.componentId[cell]]?.size||0)<game.landCount*.02?1.5:0;score+=(gRandom()-.5)*(10/Math.max(.6,d.foresight));if(score>bestScore){bestScore=score;best=cell}}return best}
function thinkOneAI(p){const d=aiDifficulty(),reserve=desiredReserve(p),underPressure=p.recentLoss>Math.max(5,p.cells.size*.025);if((underPressure||p.balance<reserve*.46)&&p.attacks>0)cancelOneAttack(p.id);if(p.attacks>=3||p.balance<Math.max(60,reserve*.42))return;const contacts=game.contacts[p.id]||new Map(),choices=[];for(const [target,info] of contacts){const score=evaluateContact(p.id,target,info,d)+(gRandom()-.5)*d.noise;choices.push({target,info,score})}choices.sort((a,b)=>b.score-a.score);let pick=choices[0];if(choices.length>1&&gRandom()<d.mistake)pick=choices[Math.min(choices.length-1,1+((gRandom()*Math.min(3,choices.length-1))|0))];const saturation=componentSaturation(p),considerSea=p.coast.size>0&&(p.behavior==='navigator'||!pick||saturation>.34||p.components.size<2&&p.cells.size>game.landCount*.014);let seaPlan=null;if(considerSea&&p.balance>reserve*(p.behavior==='navigator'?.58:.66))seaPlan=findAINavalPlan(p.id,d);if(seaPlan){const seaBias=p.behavior==='navigator'?-12:p.behavior==='expansionist'?-6:p.behavior==='opportunist'?0:6,landScore=pick?.score??-999;if(!pick||seaPlan.score>landScore+seaBias||saturation>.66){const info={count:4},raw=chooseAttackPct(p,seaPlan.owner===NEUTRAL?NEUTRAL:seaPlan.owner,info,d),pct=seaPlan.owner===NEUTRAL?clamp(raw||18,15,40):clamp(raw||22,18,56);if(startNavalAttack(p.id,seaPlan.owner,pct,seaPlan.target,true,seaPlan.source))return}}if(pick&&pick.score>d.threshold){const readiness=pick.target===NEUTRAL?.54:p.behavior==='aggressive'?.68:p.behavior==='defensive'?.96:.80;if(p.balance<reserve*readiness)return;const pct=chooseAttackPct(p,pick.target,pick.info,d);if(pct>=12){const sample=chooseAIFrontCell(pick,d);startAttack(p.id,pick.target,pct,true,sample)}}}
function updateAI(dt){if(game.aiFrozen)return;const d=aiDifficulty();for(let i=0;i<game.players.length;i++){if(i===game.human&&!game.spectator)continue;const p=game.players[i];if(!p.alive)continue;if(p.behavior==='human')p.behavior=p.baseBehavior||'opportunist';p.think-=dt;if(p.think<=0){p.think=d.interval*gRand(1.2,.82);thinkOneAI(p)}}}

// ---------- Events / tutorial / HUD ----------
function pushEvent(text,kind='war',ttl=7){if(!text)return;game.events.unshift({text,kind,ttl});game.events=game.events.slice(0,4);renderEventFeed()}
function renderEventFeed(){const e=$('#eventFeed');if(!e)return;e.innerHTML=game.events.map(x=>`<div class="feedItem ${x.kind}">${escapeHTML(x.text)}</div>`).join('');e.style.display=prefs.eventFeed?'flex':'none'}
function updateEvents(dt){let changed=false;for(const e of game.events)e.ttl-=dt;const n=game.events.filter(e=>e.ttl>0);if(n.length!==game.events.length){game.events=n;changed=true}if(changed)renderEventFeed()}
function borderDirection(cell){const p=humanPlayer();let cx=game.GW/2,cy=game.GH/2;if(p?.cells.size){let sx=0,sy=0,n=0,k=0,step=Math.max(1,Math.floor(p.cells.size/80));for(const c of p.cells){if(k++%step)continue;sx+=c%game.GW;sy+=(c/game.GW)|0;n++}if(n){cx=sx/n;cy=sy/n}}const x=cell%game.GW,y=(cell/game.GW)|0,dx=x-cx,dy=y-cy;return Math.abs(dx)>Math.abs(dy)?dx<0?'western':'eastern':dy<0?'northern':'southern'}

function showCoach(html){const c=$('#coach');c.innerHTML=html;c.classList.add('show')}function hideCoach(){$('#coach').classList.remove('show')}
function advanceTutorial(event){if(!game.tutorialActive)return;if(event==='spawn'&&game.tutorialStage===0){game.tutorialStage=1;showCoach('<b>2/4 · Expand</b> Tap nearby neutral land. Start with 25–50%, then let your reserve rebuild.')}else if(event==='neutralAttack'&&game.tutorialStage===1){game.tutorialStage=2;showCoach('<b>3/4 · Timing</b> Your home reserve defends every border. Sending ALL makes you easy to punish.')}else if(event==='enemyAttack'&&game.tutorialStage<=2){game.tutorialStage=3;showCoach('<b>4/4 · Fronts</b> Where you tap matters. Attack weak fronts and chokepoints instead of wasting troops.')}else if(event==='naval'){completeTutorial()}}
function completeTutorial(){if(!game.tutorialActive)return;game.tutorialActive=false;prefs.tutorialSeen=true;savePrefs();showCoach('<b>Tutorial complete.</b> Build reserves, watch weakened rivals, and use the sea when geography demands it.');setTimeout(hideCoach,4500)}
function updateTutorial(dt){if(!game.tutorialActive)return;game.tutorialTimer+=dt;if(game.tutorialStage===3&&game.tutorialTimer>48){showCoach('<b>Naval tip</b> Tap a reachable island or coast across water to launch an invasion.');if(game.tutorialTimer>68)completeTutorial()}}
function updateHUD(){const p=humanPlayer();if(!p){$('#troopsTxt').textContent='SPECTATOR';$('#landTxt').textContent='Free camera';$('#growthTxt').textContent='AI live';$('#rankTxt').textContent='—';return}const pct=p.cells.size/Math.max(1,game.landCount)*100,rank=strategicRankings().findIndex(x=>x.id===p.id)+1,eff=Math.round(economyEfficiency(p)*100),send=p.balance*game.attackPct/100,reserve=Math.max(0,p.balance-send);game.maxHumanPct=Math.max(game.maxHumanPct,pct);$('#troopsTxt').textContent=fmt(p.balance)+' troops';$('#landTxt').textContent=pct.toFixed(2)+'% land';$('#growthTxt').textContent='+'+fmt(growthRate(p))+'/s';$('#rankTxt').textContent='#'+rank;const ee=$('#efficiencyTxt');ee.textContent=eff+'% eff.';ee.classList.toggle('low',eff<72);$('#sendPreview').textContent=`Send ${fmt(send)} · keep ${fmt(reserve)}`;$('#percentBadge').textContent=game.attackPct+'%';const risk=game.attackPct>=85?'CRITICAL RISK':game.attackPct>=65?'HIGH COMMITMENT':eff<70?'LOW EFFICIENCY':'Reserve healthy';$('#frontStatus').textContent=game.lastTarget>=0?`${risk} · targeting ${game.owner[game.lastTarget]===NEUTRAL?'neutral land':game.players[game.owner[game.lastTarget]]?.name||'front'}`:`${risk} · tap a border to choose a front`;const limit=game.rules.timeLimit;$('#gameTimer').textContent=limit?`${game.mode.name} · ${game.map.name} · ${timeFmt(Math.max(0,limit-game.time))}`:`${game.mode.name} · ${game.map.name}`}

function updateLeaderboard(initial=false){if(!game.players.length)return;const ranked=strategicRankings(),top=ranked.slice(0,6),me=humanPlayer(),rank=me?ranked.findIndex(p=>p.id===me.id)+1:-1;if(me&&rank>6&&me.alive)top.push(me);$('#leaderRows').innerHTML=top.map((p,j)=>{const r=me&&p.id===me.id?rank:j+1,pct=p.cells.size/Math.max(1,game.landCount)*100;return`<div class="leaderRow ${me&&p.id===me.id?'me':''}" data-pid="${p.id}"><span>${r}</span><i class="dot" style="background:${p.color}"></i><span class="nm">${AVATAR_EMOJI[p.avatar]||'◉'} ${escapeHTML(p.name)}</span><span class="pct">${pct.toFixed(1)}%</span></div>`}).join('');$$('#leaderRows .leaderRow').forEach(e=>e.onclick=()=>inspectNation(+e.dataset.pid));const leader=ranked[0]?.id??-1;if(initial){game.lastLeader=leader;game.announcedLeader=-1;game.leaderSince=game.time;return}if(leader!==game.lastLeader){game.lastLeader=leader;game.leaderSince=game.time;return}if(game.spawned&&game.time>15&&leader!==game.announcedLeader&&game.time-game.leaderSince>4){const lp=game.players[leader];if(lp){pushEvent(me&&leader===me.id?'You became #1':`${lp.name} took the lead`,me&&leader===me.id?'good':'war');if(me&&leader===me.id){soundEvent('lead');haptic(10)}}game.announcedLeader=leader}}

function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
let noticeTimer=0;function flashNotice(t){const n=$('#notice');n.textContent=t;n.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.classList.remove('show'),1750)}

// ---------- Simulation / end conditions ----------
function simulate(realDt){if(game.paused||game.over)return;if(game.spawnLeft>0){game.spawnLeft=Math.max(0,game.spawnLeft-realDt);const cd=Math.ceil(game.spawnLeft);$('#spawnOverlay .spawnCount').textContent=cd;if(cd!==game.lastCountdown){game.lastCountdown=cd;if(cd<=3&&cd>0)soundEvent('count')}if(game.spawnLeft<=0){if(!game.spawned){const s=findSpawn(2);if(s>=0){claimSpawn(Math.max(0,game.human),s,game.rules.spawnRadius||2);game.spawned=true;advanceTutorial('spawn')}}soundEvent('go');$('#spawnOverlay').style.display='none';rebuildAllBorders();rebuildContacts();assignStrategicColors();flashNotice('Build a reserve, then choose your front')}}else{const dt=realDt*game.rules.gameSpeed;game.time+=dt;updateEconomy(dt);processAttacks(dt);processNavals(dt);game.contactAcc+=dt;if((game.contactDirty&&game.contactAcc>=.18)||game.contactAcc>=.65){game.contactAcc=0;rebuildContacts()}updateAI(dt);checkEndConditions();updateTutorial(dt);updateEvents(dt)}updateFx(realDt);game.hudAcc+=realDt;game.miniAcc+=realDt;game.labelAcc+=realDt;if(game.hudAcc>.24){game.hudAcc=0;updateHUD();updateLeaderboard()}const miniEvery=prefs.batterySaver?1.7:1;if(game.miniAcc>miniEvery){game.miniAcc=0;updateMinimap()}const labEvery=prefs.batterySaver?2.4:1.25;if(game.labelAcc>labEvery){game.labelAcc=0;computeLabels()}}

function inspectNation(pid){const p=game.players[pid];if(!p)return;game.inspected=pid;drawAvatarCanvas($('#inspectAvatar'),p.avatar,p.avatarImage||'',p.color);$('#inspectName').textContent=p.name;const rank=Math.max(1,strategicRankings().findIndex(x=>x.id===pid)+1),pct=p.cells.size/Math.max(1,game.landCount)*100,trend=p.recentGain-p.recentLoss,contacts=[...(game.contacts[pid]?.keys()||[])].filter(x=>x>=0&&game.players[x]?.alive).length;$('#inspectMeta').textContent=`${pid===game.human?'CONTROLLED · ':''}${p.behavior==='human'?'Commander':p.behavior[0].toUpperCase()+p.behavior.slice(1)} · Rank #${rank}`;$('#inspectStats').innerHTML=`<span>${fmt(p.balance)} troops</span><span>${pct.toFixed(1)}% land</span><span>${trend>3?'Growing':trend<-3?'Losing ground':'Stable'}</span><span>${contacts} fronts</span>`;$('#nationInspect').classList.add('open')}
function closeInspection(){game.inspected=-1;$('#nationInspect').classList.remove('open')}
function refreshSandboxNationList(){const sel=$('#sandboxNation');if(!sel)return;const old=+sel.value;sel.innerHTML=game.players.map(p=>`<option value="${p.id}">${p.id===game.human?'★ ':''}${escapeHTML(p.name)}${p.alive?'':' · eliminated'}</option>`).join('');const wanted=game.players[old]?old:clamp(game.sandboxSelected||1,0,game.players.length-1);sel.value=String(wanted);game.sandboxSelected=wanted}
function openSandboxTools(){if(!game.rules?.sandbox)return;game.paused=true;game.sandboxEditing=false;document.documentElement.classList.remove('sandboxPainting');$('#sandboxBar').classList.remove('open');refreshSandboxNationList();$('#sbGrowth').value=Math.round(game.rules.growth*100);$('#sbSpeed').value=Math.round(game.rules.gameSpeed*100);$('#sbGrowthValue').textContent=game.rules.growth.toFixed(1)+'×';$('#sbSpeedValue').textContent=game.rules.gameSpeed.toFixed(1)+'×';$('#sbBrush').value=game.sandboxBrush;$('#sbBrushValue').textContent=game.sandboxBrush;$('#freezeAiBtn').textContent=game.aiFrozen?'Unfreeze AI':'Freeze AI';$('#sandboxModal').classList.add('open')}
function selectedSandboxNation(){return game.players[clamp(game.sandboxSelected|0,0,game.players.length-1)]}
function armSandboxPaint(mode,pid=game.sandboxSelected){if(!game.rules?.sandbox)return;game.sandboxEditing=true;game.sandboxPaint={mode,pid};$('#sandboxModal').classList.remove('open');$('#pauseOverlay').classList.remove('open');$('#sandboxBar').classList.add('open');document.documentElement.classList.add('sandboxPainting');const p=pid>=0?game.players[pid]:null;$('#sandboxBarText').textContent=mode==='neutral'?'PAINT NEUTRAL':mode==='spawn'?`SPAWN ${p?.name||'NATION'}`:`PAINT ${p?.name||'TERRITORY'}`;flashNotice('Sandbox editor active · tap or drag on land')}
function scheduleSandboxRender(){if(game.sandboxRenderPending)return;game.sandboxRenderPending=true;requestAnimationFrame(()=>{game.sandboxRenderPending=false;if(game.borderDirty)redrawBorders();renderGame();updateMinimap()})}
function sandboxPaintCell(cell){if(!game.rules?.sandbox||!game.sandboxPaint||cell<0||game.owner[cell]===WATER)return;const {mode,pid}=game.sandboxPaint;if(mode==='spawn'){if(game.owner[cell]!==NEUTRAL){flashNotice('Choose neutral land to spawn this nation');return}const p=game.players[pid];p.balance=Math.max(p.balance,game.rules.startTroops);p.alive=true;claimSpawn(pid,cell,game.rules.spawnRadius||2);rebuildAllBorders();rebuildContacts();paintWholeWorld();refreshSandboxNationList();game.sandboxPaint=null;game.sandboxEditing=false;document.documentElement.classList.remove('sandboxPainting');$('#sandboxBar').classList.remove('open');$('#pauseOverlay').classList.add('open');flashNotice(`${p.name} deployed`);scheduleSandboxRender();return}const target=mode==='neutral'?NEUTRAL:pid,cx=cell%game.GW,cy=(cell/game.GW)|0,r=game.sandboxBrush||2;for(let y=Math.max(0,cy-r);y<=Math.min(game.GH-1,cy+r);y++)for(let x=Math.max(0,cx-r);x<=Math.min(game.GW-1,cx+r);x++){if((x-cx)**2+(y-cy)**2>r*r)continue;const i=y*game.GW+x;if(game.owner[i]!==WATER)setOwner(i,target,false)}game.contactDirty=true;game.dirty=true;scheduleSandboxRender()}
function stopAllOperations(){game.attacks.length=0;game.navals.length=0;for(const p of game.players)p.attacks=0;flashNotice('All active operations cancelled')}
function eliminateNationSandbox(pid){const p=game.players[pid];if(!p)return;const cells=[...p.cells];for(const c of cells)setOwner(c,NEUTRAL,false);p.balance=0;p.alive=false;p.attacks=0;refreshSandboxNationList();flashNotice(`${p.name} removed from the map`)}
function controlNation(pid){const p=game.players[pid];if(!p?.alive){flashNotice('Revive or spawn that nation first');return}if(game.human>=0&&game.players[game.human])game.players[game.human].behavior=game.players[game.human].baseBehavior||'opportunist';game.human=pid;game.spectator=false;p.behavior='human';game.pendingAttack=null;game.lastTarget=-1;refreshSandboxNationList();updateHUD(true);updateLeaderboard(true);flashNotice(`Now controlling ${p.name}`)}
function enterSpectator(){if(game.human>=0&&game.players[game.human])game.players[game.human].behavior=game.players[game.human].baseBehavior||'opportunist';game.human=-1;game.spectator=true;game.pendingAttack=null;updateHUD(true);refreshSandboxNationList();flashNotice('Spectator mode enabled')}
function centerOnNation(pid){const p=game.players[pid];if(!p?.cells.size)return;let sx=0,sy=0,n=0,k=0,step=Math.max(1,Math.floor(p.cells.size/250));for(const c of p.cells){if((k++%step)!==0)continue;sx+=c%game.GW;sy+=(c/game.GW)|0;n++}if(!n)return;const wx=sx/n,wy=sy/n,z=Math.max(1.5,Math.min(3.6,game.cam.zoom));setZoomFocus(wx,wy,viewW/2,viewH/2,z);game.dirty=true}
function forceWarSandbox(){const a=selectedSandboxNation(),def=humanPlayer();if(!a?.alive||!def?.alive||a.id===def.id){flashNotice('Select another living nation while controlling one');return}const was=game.paused;game.paused=false;rebuildContacts();let cell=game.contacts[a.id]?.get(def.id)?.samples?.[0]??-1;if(cell<0&&def.coast.size)cell=[...def.coast][0];const ok=cell>=0&&startAttack(a.id,def.id,55,true,cell);game.paused=was;if(ok)pushEvent(`${a.name} was ordered to attack ${def.name}`,'war');else flashNotice('No valid land or naval route for that forced war')}
function bindSandboxTools(){if(bindSandboxTools.done)return;bindSandboxTools.done=true;$('#sandboxClose').onclick=()=>{$('#sandboxModal').classList.remove('open');$('#pauseOverlay').classList.add('open');soundEvent('close')};$('#sandboxNation').onchange=e=>{game.sandboxSelected=+e.target.value;inspectNation(game.sandboxSelected)};$$('[data-troops]').forEach(b=>b.onclick=()=>{const p=selectedSandboxNation();if(!p)return;p.balance=Math.max(0,p.balance+(+b.dataset.troops));p.alive=p.cells.size>0;flashNotice(`${p.name}: ${fmt(p.balance)} troops`);soundEvent('tap')});$('#sbGrowth').oninput=e=>{game.rules.growth=+e.target.value/100;$('#sbGrowthValue').textContent=game.rules.growth.toFixed(1)+'×';soundEvent('slider')};$('#sbSpeed').oninput=e=>{game.rules.gameSpeed=+e.target.value/100;$('#sbSpeedValue').textContent=game.rules.gameSpeed.toFixed(1)+'×';soundEvent('slider')};$('#sbBrush').oninput=e=>{game.sandboxBrush=+e.target.value;$('#sbBrushValue').textContent=game.sandboxBrush;soundEvent('slider')};$('#paintSelfBtn').onclick=()=>{if(game.human<0)return flashNotice('Control a nation first');armSandboxPaint('nation',game.human)};$('#paintSelectedBtn').onclick=()=>armSandboxPaint('nation',game.sandboxSelected);$('#paintNeutralBtn').onclick=()=>armSandboxPaint('neutral',-1);$('#spawnNationBtn').onclick=()=>armSandboxPaint('spawn',game.sandboxSelected);$('#controlNationBtn').onclick=()=>{controlNation(game.sandboxSelected);openSandboxTools()};$('#spectatorBtn').onclick=()=>{enterSpectator();openSandboxTools()};$('#eliminateNationBtn').onclick=()=>{eliminateNationSandbox(game.sandboxSelected);openSandboxTools()};$('#forceWarBtn').onclick=()=>{forceWarSandbox();openSandboxTools()};$('#freezeAiBtn').onclick=()=>{game.aiFrozen=!game.aiFrozen;$('#freezeAiBtn').textContent=game.aiFrozen?'Unfreeze AI':'Freeze AI';flashNotice(game.aiFrozen?'AI frozen':'AI resumed')};$('#stopAttacksBtn').onclick=stopAllOperations;$('#instantWinBtn').onclick=()=>finishGame(true,'Sandbox outcome forced: victory.');$('#instantLoseBtn').onclick=()=>finishGame(false,'Sandbox outcome forced: defeat.');$('#sandboxIntelBtn').onclick=()=>{game.sandboxIntel=!game.sandboxIntel;prefs.showLabels=true;applyLiveSettings();computeLabels();flashNotice(game.sandboxIntel?'Debug intel enabled':'Debug intel disabled')};$('#sandboxRevealBtn').onclick=()=>centerOnNation(game.sandboxSelected);$('#sandboxEditorBack').onclick=()=>openSandboxTools();$('#sandboxPaintDone').onclick=()=>{game.sandboxEditing=false;game.sandboxPaint=null;document.documentElement.classList.remove('sandboxPainting');$('#sandboxBar').classList.remove('open');$('#pauseOverlay').classList.add('open')};}
function checkEndConditions(){if(game.rules?.sandbox)return;const me=humanPlayer(),alive=game.players.filter(p=>p.alive&&p.cells.size>0);if(!me)return;if(game.spawned&&me.cells.size===0){finishGame(false,'Your territory was eliminated.');return}if(me.cells.size>game.landCount*(game.rules.victory/100)){finishGame(true,`You control ${game.rules.victory}% of the map.`);return}if(alive.length===1&&alive[0].id===me.id){finishGame(true,'You are the last nation standing.');return}if(game.rules.timeLimit&&game.time>=game.rules.timeLimit){const ranked=strategicRankings(),rank=ranked.findIndex(p=>p.id===me.id)+1;finishGame(rank===1,rank===1?'Time expired — you hold the most land.':'Time expired. Largest territory wins.')}}
function finishGame(win,sub){if(game.over)return;game.over=true;game.paused=true;game.winner=win;const me=humanPlayer()||game.players[0],ranked=strategicRankings(),rank=Math.max(1,ranked.findIndex(p=>p.id===me.id)+1),landPct=me.cells.size/Math.max(1,game.landCount)*100,record={map:game.map.name,mode:game.mode.name,difficulty:prefs.difficulty,win:!!win,rank,land:landPct,elims:me.elims||game.eliminations,time:game.time,unranked:!game.rules.stats};stats.history=[record,...(stats.history||[])].slice(0,12);if(game.rules.stats){stats.games++;stats.wins+=win?1:0;stats.losses+=win?0:1;stats.totalRank+=rank;stats.bestRank=Math.min(stats.bestRank,rank);stats.largestTerritory=Math.max(stats.largestTerritory,game.maxHumanPct);stats.totalCaptured+=game.captured;stats.eliminations+=game.eliminations;stats.totalAttacks+=game.attacksLaunched;stats.navalInvasions+=game.navalsLaunched;stats.navalSuccess+=game.navalsSucceeded;stats.longestMatch=Math.max(stats.longestMatch,game.time);if(win)stats.fastestVictory=stats.fastestVictory?Math.min(stats.fastestVictory,game.time):game.time;stats.mapGames[game.mapId]=(stats.mapGames[game.mapId]||0)+1;if(win)stats.mapWins[game.mapId]=(stats.mapWins[game.mapId]||0)+1;if(win)stats.diffWins[prefs.difficulty]=(stats.diffWins[prefs.difficulty]||0)+1}saveStats();$('#resultIcon').textContent=win?'🏆':'◆';$('#resultTitle').textContent=win?'Sovereign Victory':'Campaign Ended';$('#resultSub').textContent=sub+(game.rules.stats?'':' · Unranked campaign');drawAvatarCanvas($('#resultAvatar'),me.avatar,me.avatarImage||'',me.color);$('#resultProfileName').textContent=me.name;$('#resultProfileLine').textContent=`${game.map.name} · ${game.mode.name} · ${prefs.difficulty}`;$('#resultRank').textContent='#'+rank;$('#resultLand').textContent=landPct.toFixed(1)+'%';$('#resultElims').textContent=me.elims||game.eliminations;$('#resultAttacks').textContent=game.attacksLaunched;$('#resultNaval').textContent=`${game.navalsSucceeded}/${game.navalsLaunched}`;$('#resultCaptured').textContent=game.captured.toLocaleString();$('#resultTime').textContent=timeFmt(game.time);$('#resultPeak').textContent=Math.max(game.maxHumanPct,landPct).toFixed(1)+'%';$('#resultOverlay').classList.add('open');document.documentElement.classList.remove('sandboxPainting');$('#sandboxBar').classList.remove('open');soundEvent(win?'win':'lose');haptic(win?[35,45,35,45,58]:[42,30,52])}
function pauseGame(auto=false){if(!game.running||game.over)return;game.paused=true;game.autoPaused=auto;soundEvent('pause');const p=humanPlayer(),rank=p?strategicRankings().findIndex(x=>x.id===p.id)+1:0,pct=p?p.cells.size/Math.max(1,game.landCount)*100:0;$('#pauseSubtitle').textContent=`${game.mode.name} · ${game.map.name}${game.rules.stats?'':' · UNRANKED'}`;$('#pauseMapInfo').textContent=game.map.name;$('#pauseRankInfo').textContent=p?'#'+rank:'Spectator';$('#pauseLandInfo').textContent=p?pct.toFixed(1)+'%':'—';$('#sandboxToolsBtn').style.display=game.rules?.sandbox?'flex':'none';$('#pauseOverlay').classList.add('open')}function resumeGame(){if(game.over)return;soundEvent('resume');game.paused=false;game.autoPaused=false;$('#pauseOverlay').classList.remove('open');$('#sandboxModal').classList.remove('open');game.lastTS=performance.now();if(game.rafId)cancelAnimationFrame(game.rafId);game.rafId=requestAnimationFrame(loop)}function endToMenu(){game.running=false;game.paused=false;game.over=false;if(game.rafId){cancelAnimationFrame(game.rafId);game.rafId=0}$('#pauseOverlay').classList.remove('open');$('#resultOverlay').classList.remove('open');$('#sandboxModal').classList.remove('open');$('#sandboxBar').classList.remove('open');document.documentElement.classList.remove('sandboxPainting','showTarget');closeInspection();hideCoach();showScreen('menu');renderStats();updateProfileSurfaces();syncMusic()}

// ---------- Mobile input / camera ----------
let pointers=new Map(),gesture={drag:false,pinch:false,hadPinch:false,startX:0,startY:0,startPanX:0,startPanY:0,startTime:0,lastX:0,lastY:0,lastMove:0,vx:0,vy:0,startDist:0,startZoom:1,pinchWorldX:0,pinchWorldY:0,longTimer:0,longFired:false};
function screenToWorld(sx,sy,tr=getTransform()){return{x:(sx-tr.x)/tr.s,y:(sy-tr.y)/tr.s}}function screenToCell(sx,sy){const w=screenToWorld(sx,sy),x=Math.floor(w.x),y=Math.floor(w.y);return x<0||y<0||x>=game.GW||y>=game.GH?-1:y*game.GW+x}
function setZoomFocus(worldX,worldY,screenX,screenY,z){game.cam.zoom=clamp(z,1,8);const s=baseScale()*game.cam.zoom;game.cam.panX=screenX-(viewW-game.GW*s)/2-worldX*s;game.cam.panY=screenY-(viewH-game.GH*s)/2-worldY*s;clampCamera();game.dirty=true}
function clearLongPress(){if(gesture.longTimer){clearTimeout(gesture.longTimer);gesture.longTimer=0}}
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);game.cam.vx=game.cam.vy=0;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(game.rules?.sandbox&&game.sandboxEditing){sandboxPaintCell(screenToCell(e.clientX,e.clientY));return}if(pointers.size===1){Object.assign(gesture,{drag:false,pinch:false,hadPinch:false,longFired:false,startX:e.clientX,startY:e.clientY,startPanX:game.cam.panX,startPanY:game.cam.panY,startTime:performance.now(),lastX:e.clientX,lastY:e.clientY,lastMove:performance.now(),vx:0,vy:0});clearLongPress();gesture.longTimer=setTimeout(()=>{if(!gesture.drag&&!gesture.pinch&&pointers.size===1){const cell=screenToCell(e.clientX,e.clientY),o=cell>=0?game.owner[cell]:WATER;if(o>=0){gesture.longFired=true;inspectNation(o);haptic(8)}}},470)}else if(pointers.size===2){clearLongPress();gesture.pinch=true;gesture.hadPinch=true;const[a,b]=[...pointers.values()],mx=(a.x+b.x)/2,my=(a.y+b.y)/2;gesture.startDist=Math.hypot(a.x-b.x,a.y-b.y);gesture.startZoom=game.cam.zoom;const w=screenToWorld(mx,my);gesture.pinchWorldX=w.x;gesture.pinchWorldY=w.y}});
canvas.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;e.preventDefault();pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(game.rules?.sandbox&&game.sandboxEditing){sandboxPaintCell(screenToCell(e.clientX,e.clientY));return}if(pointers.size===1&&!gesture.pinch){const p=[...pointers.values()][0],sens=(prefs.cameraSensitivity||100)/100,dx=(p.x-gesture.startX)*sens,dy=(p.y-gesture.startY)*sens;if(Math.hypot(dx,dy)>11){gesture.drag=true;clearLongPress()}if(gesture.drag){game.cam.panX=gesture.startPanX+dx;game.cam.panY=gesture.startPanY+dy;const now=performance.now(),dt=Math.max(.008,(now-gesture.lastMove)/1000);gesture.vx=(p.x-gesture.lastX)/dt*sens;gesture.vy=(p.y-gesture.lastY)/dt*sens;gesture.lastX=p.x;gesture.lastY=p.y;gesture.lastMove=now;clampCamera();game.dirty=true}}else if(pointers.size>=2){clearLongPress();const[a,b]=[...pointers.values()],dist=Math.hypot(a.x-b.x,a.y-b.y),mx=(a.x+b.x)/2,my=(a.y+b.y)/2,sens=(prefs.cameraSensitivity||100)/100,newZoom=gesture.startZoom*Math.pow(dist/Math.max(20,gesture.startDist),sens);setZoomFocus(gesture.pinchWorldX,gesture.pinchWorldY,mx,my,newZoom)}});
canvas.addEventListener('pointerup',e=>{if(!pointers.has(e.pointerId))return;clearLongPress();const wasSingle=pointers.size===1&&!gesture.pinch&&!gesture.hadPinch,p=pointers.get(e.pointerId),elapsed=performance.now()-gesture.startTime;pointers.delete(e.pointerId);if(game.rules?.sandbox&&game.sandboxEditing)return;if(wasSingle&&!gesture.drag&&!gesture.longFired&&elapsed<700)handleMapTap(p.x,p.y);else if(gesture.drag&&prefs.panInertia){game.cam.vx=clamp(gesture.vx,-2200,2200);game.cam.vy=clamp(gesture.vy,-2200,2200)}if(pointers.size<2)gesture.pinch=false;if(pointers.size===1){const q=[...pointers.values()][0];Object.assign(gesture,{startX:q.x,startY:q.y,startPanX:game.cam.panX,startPanY:game.cam.panY,drag:false,lastX:q.x,lastY:q.y,lastMove:performance.now()})}});
canvas.addEventListener('pointercancel',e=>{clearLongPress();pointers.delete(e.pointerId);gesture.pinch=false;gesture.hadPinch=true});
mini.addEventListener('pointerdown',e=>{if(!prefs.showMinimap||!game.running)return;e.preventDefault();const r=mini.getBoundingClientRect(),wx=(e.clientX-r.left)/r.width*game.GW,wy=(e.clientY-r.top)/r.height*game.GH,s=baseScale()*game.cam.zoom;game.cam.panX=viewW/2-(viewW-game.GW*s)/2-wx*s;game.cam.panY=viewH/2-(viewH-game.GH*s)/2-wy*s;game.cam.vx=game.cam.vy=0;clampCamera();game.dirty=true;haptic(5)});
function handleMapTap(x,y){const i=screenToCell(x,y);if(i<0||game.owner[i]===WATER)return;if(game.rules?.sandbox&&game.sandboxEditing){sandboxPaintCell(i);return}if(game.paused||game.over)return;if(game.spectator||game.human<0){const o=game.owner[i];if(o>=0)inspectNation(o);return}const me=humanPlayer();if(!me)return;if(game.spawnLeft>0){if(game.spawned){flashNotice('Start already chosen');return}if(game.owner[i]!==NEUTRAL){flashNotice('Choose unclaimed land');return}const comp=game.components[game.componentId[i]];if(comp&&comp.size<Math.max(18,game.landCount*.004)){flashNotice('Small island — limited expansion');haptic(8)}if(claimSpawn(game.human,i,game.rules.spawnRadius||2)){game.spawned=true;rebuildAllBorders();rebuildContacts();assignStrategicColors();soundEvent('spawn');haptic(22);addFx(i,me.color,'land');flashNotice('Capital established');advanceTutorial('spawn')}return}if(!game.spawned)return;const target=game.owner[i];game.lastTarget=i;const targetEl=$('#targetReadout');document.documentElement.classList.add('showTarget');targetEl.classList.remove('targetDanger','targetNaval');if(target===game.human){game.pendingAttack=null;targetEl.textContent=`${me.name} · ${fmt(me.balance)} troops · your territory`;inspectNation(game.human);return}const front=collectFrontSeeds(game.human,target,i,1),naval=!front.seeds.length,name=target===NEUTRAL?'Neutral territory':game.players[target]?.name||'Unknown';targetEl.textContent=`${naval?'NAVAL':'LAND'} · ${name} · commit ${game.attackPct}% (${fmt(me.balance*game.attackPct/100)})`;targetEl.classList.add(naval?'targetNaval':'targetDanger');if(prefs.confirmLargeAttacks&&game.attackPct>=85){const now=performance.now(),same=game.pendingAttack&&game.pendingAttack.cell===i&&now-game.pendingAttack.time<2200;if(!same){game.pendingAttack={cell:i,time:now};soundEvent('count');haptic(10);flashNotice(`High risk: tap again to confirm ${game.attackPct}%`);addFx(i,'#ffb84a');return}game.pendingAttack=null}if(!startAttack(game.human,target,game.attackPct,false,i))flashNotice(game.time<(game.rules.peacefulStart||0)?'Peace period is still active':'No reachable front — target may be outside naval range')}

// ---------- Main loop / lifecycle ----------
function loop(ts){game.rafId=0;if(!game.running||game.paused)return;let elapsed=Math.min(1,Math.max(0,(ts-game.lastTS)/1000));game.lastTS=ts;game.simAcc+=elapsed;let steps=0;while(game.simAcc>=SIM_STEP&&steps<30){simulate(SIM_STEP);game.simAcc-=SIM_STEP;steps++}updateCameraMotion(elapsed);const cap=renderFpsCap(),renderDue=ts-game.lastRenderTS>=1000/cap;if(renderDue){game.lastRenderTS=ts;if(game.dirty||game.borderDirty||game.navals.length||game.attacks.length||game.fx.length||(prefs.oceanFx&&prefs.quality!=='Low'))renderGame();game.fpsFrames++}if(ts-game.fpsLast>650){game.fps=Math.round(game.fpsFrames*1000/(ts-game.fpsLast||1000));game.fpsFrames=0;game.fpsLast=ts;if(prefs.showFPS)$('#fps').textContent=game.fps+' FPS'}game.rafId=requestAnimationFrame(loop)}
window.addEventListener('resize',()=>{resizeCanvas();if(game.running){renderGame();updateMinimap()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){stopMusic();if(game.running&&!game.paused&&!game.over)pauseGame(true)}else syncMusic()});document.addEventListener('contextmenu',e=>e.preventDefault());document.addEventListener('gesturestart',e=>e.preventDefault(),{passive:false});

// ---------- Boot ----------
initUI();applyLiveSettings();updateAttackControls();resetMenuBG();requestAnimationFrame(menuAnim);resizeCanvas();
